try{$user=(new Auth($config))->requireUser();$config['workspace']=UserStorage::home($config,(int)$user['id']);$input=request_json();$text=trim((string)($input['message']??''));if($text==='')json_response(['ok'=>false,'error'=>'Mensagem vazia.'],400);$pdo=null;$conversationId=(int)($input['conversation_id']??0);if((int)$user['id']>0){$pdo=Database::connection($config);if($conversationId){$s=$pdo->prepare('SELECT id FROM conversations WHERE id=? AND user_id=?');$s->execute([$conversationId,(int)$user['id']]);if(!$s->fetch())throw new RuntimeException('Conversa inválida.');}else{$s=$pdo->prepare('INSERT INTO conversations(user_id,title,provider) VALUES(?,?,?)');$s->execute([(int)$user['id'],(function_exists('mb_substr')?mb_substr($text,0,80):substr($text,0,80)),$config['llm']['provider']]);$conversationId=(int)$pdo->lastInsertId();}$s=$pdo->prepare('INSERT INTO messages(conversation_id,role,content) VALUES(?,?,?)');$s->execute([$conversationId,'user',$text]);}$workspace=new WorkspaceService($config);$tools=new ToolRegistry($workspace,$config);$provider=new LlmProvider($config);$events=[['type'=>'plan','text'=>'Pedido recebido. O agente vai analisar se precisa consultar a workspace.']];$messages=[['role'=>'system','content'=>'Você é o ZystemWorkSpace para IA. Responda em português. Use as ferramentas registradas. Nunca invente resultados. Não exponha raciocínio privado.'.(new SkillCatalog($config))->prompt()]];$history=array_slice((array)($input['history']??[]),-((int)($config['limits']['max_tool_history']??20)));foreach($history as $m)if(is_array($m)&&isset($m['role'],$m['content'])&&in_array($m['role'],['user','assistant'],true))$messages[]=['role'=>$m['role'],'content'=>(string)$m['content']];$messages[]=['role'=>'user','content'=>$text];for($round=0;$round<$config['limits']['max_tool_rounds'];$round++){$assistant=$provider->chat($messages,$tools->definitions());$messages[]=$assistant;$calls=$assistant['tool_calls']??[];if(!$calls&&isset($assistant['content']))$calls